-- Robotics/Embedded/IoT pathway ("Vector Division") Act 17 -- "Linux at
-- the Edge" content, closing Arc III ("Connect the Physical World," Acts
-- 14-17). World row world-vec-linux-at-the-edge already exists (created
-- earlier). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue ->
-- objectives -> challenges -> hints pattern as every other pathway. No
-- new ChallengeType needed -- reuses story_dialogue, investigation,
-- multiple_choice, interactive_diagram, drag_and_drop, browser_simulation
-- (generic console fallback) and boss_encounter, same as Act 1 and Act 5.
-- One of the fleet's aggregation gateways runs embedded Linux instead of
-- bare-metal firmware, and fails to come back up after a routine kernel
-- update. Tomas Vey and Byte trace it through boot process, kernel/user
-- space, cross compilation and root filesystems to land on a genuine,
-- mundane build mistake: the new kernel was cross-compiled for the wrong
-- target architecture and paired with a root filesystem that never
-- matched it -- not an attack. Closes on the Arc III-closing pivot into
-- Act 18, "Robot Geometry."

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-linux-at-the-edge', 'world-vec-linux-at-the-edge', 'linux-at-the-edge', '3D - Linux at the Edge', 'Learn embedded Linux as its own category next to bare-metal firmware -- boot process, kernel and user space, processes and threads, device files, GPIO and serial interfaces, systemd, cross compilation, root filesystems, and logging -- while Vector Division diagnoses an aggregation gateway that will not come back up.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-linux-at-the-edge-1', 'campaign-vec-linux-at-the-edge', 'a-different-kind-of-boot', 'A Different Kind of Boot', 'Embedded Linux vs MCU, boot process overview, kernel/user space, processes and threads, device files, and GPIO interface concepts.', 1),
  ('operation-vec-linux-at-the-edge-2', 'campaign-vec-linux-at-the-edge', 'the-gateway-that-would-not-boot', 'The Gateway That Would Not Boot', 'Serial interfaces, systemd concepts, cross compilation, root filesystems, logging and services, and the diagnosis of a gateway with a valid kernel and no valid userspace.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-linux-at-the-edge-01', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'embedded-linux-vs-mcu', 'Embedded Linux vs MCU', 'One of the fleet''s aggregation gateways fails to come back up after what should have been a routine kernel update. Tomas Vey pulls the player onto it and immediately flags the difference: this is not one of the bare-metal controllers Vector Division has spent sixteen Acts learning. It runs embedded Linux.', 'beginner', ARRAY['tomas','byte'], null, null, '{"type":"simulation","simulationId":"embedded-linux-vs-mcu-sim"}'::jsonb, '{"xp":240,"credits":25}'::jsonb, false, 1),
  ('mission-vec-linux-at-the-edge-02', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'boot-process-overview', 'Boot Process Overview', 'A bare-metal controller''s boot is one program starting to run. A Linux gateway''s boot is a relay race with several distinct runners, and the gateway stopped somewhere inside that race, not at the starting line.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"boot-process-overview-sim"}'::jsonb, '{"xp":240,"credits":30}'::jsonb, false, 2),
  ('mission-vec-linux-at-the-edge-03', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'kernel-and-user-space', 'Kernel and User Space', 'The kernel is not the whole operating system. It is the part that talks to hardware directly and hands control to everything else -- and the gateway''s kernel is reporting that it started fine.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"kernel-user-space-sim"}'::jsonb, '{"xp":250,"credits":30}'::jsonb, false, 3),
  ('mission-vec-linux-at-the-edge-04', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'processes-and-threads', 'Processes and Threads', 'A bare-metal controller runs one loop. A Linux gateway runs many independent programs at once, each with its own memory, and Byte wants the player to understand that difference before diagnosing why none of them are running right now.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"processes-and-threads-sim"}'::jsonb, '{"xp":250,"credits":35}'::jsonb, false, 4),
  ('mission-vec-linux-at-the-edge-05', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'device-files', 'Device Files', 'On a Linux gateway, hardware is not just a memory address the way it was on the bare-metal boards. It is a file, sitting in the filesystem, that a program can open and read like any other.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"device-files-sim"}'::jsonb, '{"xp":260,"credits":35}'::jsonb, false, 5),
  ('mission-vec-linux-at-the-edge-06', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-1', 'gpio-interfaces-concepts', 'GPIO Interfaces Concepts', 'The gateway still has general-purpose pins, the same concept the fleet''s bare-metal controllers use -- but on Linux, toggling one means writing through the filesystem, not writing directly to a register.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"gpio-interfaces-concepts-sim"}'::jsonb, '{"xp":260,"credits":35}'::jsonb, false, 6),
  ('mission-vec-linux-at-the-edge-07', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'serial-interfaces', 'Serial Interfaces', 'With the gateway unresponsive over the network, the only way in is a serial console cable straight into its debug port -- the same kind of physical link Vector Division has trusted since the first firmware console, still the most honest channel there is.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"serial-interfaces-sim"}'::jsonb, '{"xp":270,"credits":40}'::jsonb, false, 7),
  ('mission-vec-linux-at-the-edge-08', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'systemd-concepts', 'Systemd Concepts', 'On a normal boot, systemd is the first real userspace program, and it starts every other service the gateway needs in the right order. On this boot, the serial console shows the kernel finished and nothing after it ever spoke.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"systemd-concepts-sim"}'::jsonb, '{"xp":270,"credits":40}'::jsonb, false, 8),
  ('mission-vec-linux-at-the-edge-09', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'cross-compilation', 'Cross Compilation', 'Nobody builds a gateway''s Linux kernel on the gateway itself. It is cross-compiled on a workstation for a target processor that is not the workstation''s own -- and getting that target wrong produces a kernel that looks completely normal until it actually has to run.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"cross-compilation-sim"}'::jsonb, '{"xp":280,"credits":40}'::jsonb, false, 9),
  ('mission-vec-linux-at-the-edge-10', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'root-filesystems', 'Root Filesystems', 'A kernel with nowhere to hand off control is not really booted at all. Every program the kernel might launch -- systemd included -- has to already exist on a root filesystem built to match that exact kernel.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"root-filesystems-sim"}'::jsonb, '{"xp":280,"credits":45}'::jsonb, false, 10),
  ('mission-vec-linux-at-the-edge-11', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'logging-and-services', 'Logging and Services', 'A healthy gateway explains its own boot in its own logs. This one has none past the kernel''s own messages, because nothing past the kernel ever ran long enough to log anything at all.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"logging-and-services-sim"}'::jsonb, '{"xp":290,"credits":45}'::jsonb, false, 11),
  ('mission-vec-linux-at-the-edge-12', 'world-vec-linux-at-the-edge', 'campaign-vec-linux-at-the-edge', 'operation-vec-linux-at-the-edge-2', 'the-gateway-that-would-not-boot', 'The Gateway That Would Not Boot', 'Every concept this Act taught, turned on one gateway, closes the whole of Arc III: not an attack, not SUBSTRATE, not a hardware fault -- a kernel cross-compiled for the wrong target, paired with a root filesystem that never matched it, on a boot process that looks identical to a microcontroller''s from the outside and fails in a completely different set of places.', 'boss', ARRAY['tomas','byte','imani'], '{"requiredMissionIds":["mission-vec-linux-at-the-edge-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"gateway-would-not-boot-boss-sim"}'::jsonb, '{"xp":1300,"credits":270,"badgeIds":["the-gateway-that-would-not-boot"],"skillXp":{"robotics_fundamentals":165}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-linux-at-the-edge-01', 1, 'tomas', 'One of the fleet''s aggregation gateways has not come back up. It went down for what should have been a routine kernel update, and it has not spoken to the network since.'),
  ('mission-vec-linux-at-the-edge-01', 2, 'byte', 'I checked the asset record before pulling you in. This one is different from every controller Vector Division has diagnosed so far -- it does not run bare-metal firmware at all. It runs embedded Linux.'),
  ('mission-vec-linux-at-the-edge-01', 3, 'tomas', 'That distinction matters more than it sounds like it should. A microcontroller like the ones we have spent sixteen Acts on runs one program, written once, with no operating system underneath it. This gateway runs a full Linux kernel, with a filesystem, multiple programs, and an operating system managing all of it.'),
  ('mission-vec-linux-at-the-edge-01', 4, 'tomas', 'Same job at a glance -- collect data from the smaller controllers downstream, aggregate it, forward it upstream. Completely different internals. Which means it can fail in ways nothing we have diagnosed yet has ever failed.'),
  ('mission-vec-linux-at-the-edge-01', 5, 'byte', 'The audit that found this gateway also found the fleet''s one unauthorized part last Act -- a false alarm, in the end. This is not that. This is a real device, doing a real job, that genuinely will not start.'),
  ('mission-vec-linux-at-the-edge-01', 6, 'tomas', 'Before either of us guesses why, you need the vocabulary. Embedded Linux is not "firmware but bigger." It is a different category of system, and it deserves to be understood as one before we touch it.'),

  ('mission-vec-linux-at-the-edge-02', 1, 'tomas', 'A microcontroller''s boot is almost nothing -- power arrives, one program starts running at a fixed address, and that is the entire story. A Linux gateway''s boot is a relay race: a first-stage bootloader hands off to a second-stage bootloader, which loads and starts the kernel, which eventually hands off to userspace.'),
  ('mission-vec-linux-at-the-edge-02', 2, 'tomas', 'Each runner in that race only has one job -- start the next runner correctly. If any single handoff fails, everything after it never happens, even if every earlier stage worked perfectly.'),
  ('mission-vec-linux-at-the-edge-02', 3, 'byte', 'Which means "the gateway will not boot" is not one failure. It is a whole set of different places the relay could have dropped the baton, and diagnosing it means finding exactly which one.'),

  ('mission-vec-linux-at-the-edge-03', 1, 'tomas', 'The kernel is not the whole operating system, even though people often say "the kernel" when they mean the whole thing. The kernel is the part that talks to hardware directly -- memory, processors, devices -- and its final job in the boot sequence is handing control to userspace.'),
  ('mission-vec-linux-at-the-edge-03', 2, 'tomas', 'Userspace is everything else: the programs, services and utilities that actually do the gateway''s job, running with the kernel''s protection instead of talking to hardware directly themselves.'),
  ('mission-vec-linux-at-the-edge-03', 3, 'byte', 'The serial console output stops right at the line where the kernel finishes its own startup. Nothing after that line exists at all. Which raises the obvious question -- did the kernel actually fail, or did it succeed and simply have nothing to hand off to?'),

  ('mission-vec-linux-at-the-edge-04', 1, 'byte', 'A process is one running instance of a program, with its own private memory the kernel keeps isolated from every other process. A thread is a unit of execution inside a process -- a single process can run several threads at once, and they share that process''s memory with each other.'),
  ('mission-vec-linux-at-the-edge-04', 2, 'byte', 'A healthy gateway typically has dozens of processes running at any moment -- system services, the aggregation software itself, background utilities. Right now, past the kernel, this gateway is reporting exactly zero.'),

  ('mission-vec-linux-at-the-edge-05', 1, 'tomas', 'On the bare-metal boards, reaching hardware meant writing directly to a memory address that happened to be a register. On this gateway, the kernel exposes most hardware as a device file instead -- a file that lives in the filesystem and can be opened, read and written like any other file, even though it represents a physical device underneath.'),
  ('mission-vec-linux-at-the-edge-05', 2, 'tomas', 'That is a genuinely different model, not just a different syntax. It means a program does not need to know a hardware address at all -- only a path. And it means if the filesystem those device files live on is missing or wrong, the hardware becomes unreachable even though it is physically fine.'),

  ('mission-vec-linux-at-the-edge-06', 1, 'tomas', 'General-purpose input/output pins are the same concept you already know from every bare-metal board this Act''s Arc has covered -- pins that can be configured as input or output and toggled in software.'),
  ('mission-vec-linux-at-the-edge-06', 2, 'byte', 'The difference is entirely in how you reach them. On a microcontroller, toggling a pin means writing a bit directly to a register. On this gateway, it means writing through a GPIO device file exposed by the kernel -- same physical concept underneath, completely different path to get there.'),

  ('mission-vec-linux-at-the-edge-07', 1, 'tomas', 'The gateway has no network connection right now, which means there is exactly one way in: a serial console cable, straight into its debug header. Same idea as the very first diagnostic console Vector Division ever built, on the very first door.'),
  ('mission-vec-linux-at-the-edge-07', 2, 'tomas', 'A serial interface transmits data one bit at a time over a simple pair of wires, agreed on a fixed speed by both ends in advance. It is slow, it is old, and it is the one channel that works even when literally nothing else on the gateway has started.'),
  ('mission-vec-linux-at-the-edge-07', 3, 'byte', 'I am seeing raw kernel boot text on the serial line right now. That confirms the kernel itself is actually executing and printing output. Whatever is wrong, it is not that the board is simply dead.'),

  ('mission-vec-linux-at-the-edge-08', 1, 'tomas', 'On a normal boot, the kernel''s very last act is starting one specific userspace program: an init system. On this gateway that init system is systemd -- the first real process in userspace, and the one responsible for starting every other service the gateway needs, in the correct dependency order.'),
  ('mission-vec-linux-at-the-edge-08', 2, 'byte', 'Systemd starting is normally the loudest part of a boot log -- dozens of service lines, one after another. On this console output, there is nothing. Not "systemd failed to start a service." Not one single systemd line at all.'),
  ('mission-vec-linux-at-the-edge-08', 3, 'tomas', 'That is not a service problem. That is systemd itself never being reached in the first place -- which means whatever the kernel tried to hand control to, it was not there, or it was not something the kernel could actually run.'),

  ('mission-vec-linux-at-the-edge-09', 1, 'tomas', 'Nobody compiles a gateway''s kernel on the gateway itself -- it does not have the horsepower, and it should not need to. Engineers cross-compile it: build the kernel on a powerful workstation, but target the gateway''s actual processor architecture instead of the workstation''s own.'),
  ('mission-vec-linux-at-the-edge-09', 2, 'byte', 'I pulled the build record for this update. The kernel image was compiled correctly, with no errors, and produced a valid binary. It was cross-compiled for the wrong target architecture -- one instruction set over from what this gateway''s processor actually is.'),
  ('mission-vec-linux-at-the-edge-09', 3, 'tomas', 'And a kernel built for the wrong architecture is not corrupted. It is a perfectly well-formed binary the processor genuinely cannot execute correctly -- which explains a kernel that starts printing boot text and still never reaches a normal, complete startup.'),

  ('mission-vec-linux-at-the-edge-10', 1, 'tomas', 'A kernel alone is not a bootable system. It needs a root filesystem -- the complete set of files, libraries and programs, including the init system, that the kernel hands control to once its own job is done.'),
  ('mission-vec-linux-at-the-edge-10', 2, 'byte', 'I checked the root filesystem image paired with this update. It was built for the gateway''s correct, intended architecture -- but it was never rebuilt or verified against this specific kernel image at all. Nobody confirmed the two would actually agree with each other before deployment.'),
  ('mission-vec-linux-at-the-edge-10', 3, 'tomas', 'So the kernel is wrong for the hardware, and the root filesystem was never checked against the kernel in the first place. Two separate mistakes, and either one alone would already explain a gateway that starts and then has nowhere valid to go.'),

  ('mission-vec-linux-at-the-edge-11', 1, 'tomas', 'A healthy gateway explains its own boot afterward, in its own logs -- systemd''s journal, individual service logs, everything timestamped and queryable. That is what "logging and services" normally means in practice.'),
  ('mission-vec-linux-at-the-edge-11', 2, 'byte', 'This gateway has none of that. Not corrupted logs, not partial logs -- no logging service ever started, because nothing past the kernel ever ran long enough to start one. The only record of this boot at all is the raw kernel text still sitting on the serial line.'),

  ('mission-vec-linux-at-the-edge-12', 1, 'imani', 'Sixteen Acts of bare-metal controllers, secured end to end. Now one gateway that will not even finish booting. Walk me through it -- and remember, this closes the whole of Arc III, so make it count.'),
  ('mission-vec-linux-at-the-edge-12', 2, 'tomas', 'The serial console shows the kernel executing and printing boot text, all the way to the end of its own startup. Past that line, nothing -- no systemd, no services, no logs. The kernel did not fail. It finished, and had nothing valid to hand control to.'),
  ('mission-vec-linux-at-the-edge-12', 3, 'byte', 'The build record explains why. This update''s kernel was cross-compiled against the wrong target architecture -- a well-formed binary the gateway''s processor cannot correctly execute, even though it can start printing output before it does.'),
  ('mission-vec-linux-at-the-edge-12', 4, 'tomas', 'And the root filesystem paired with it was built for the correct architecture, but never rebuilt or verified against this exact kernel before deployment. Two mistakes stacked on top of each other -- either one alone breaks the handoff into userspace completely.'),
  ('mission-vec-linux-at-the-edge-12', 5, 'imani', 'So the fix is not a repair. It is rebuild the kernel for the correct target, and verify the kernel and root filesystem actually match before anything gets pushed to a gateway again.'),
  ('mission-vec-linux-at-the-edge-12', 6, 'tomas', 'Exactly that. And it is worth saying plainly -- a boot process that looks identical to a microcontroller''s from the outside hides an entirely different set of places it can fail. We just walked every one of them.'),
  ('mission-vec-linux-at-the-edge-12', 7, 'imani', 'The fleet is connected and secured end to end now, from bare-metal controllers to Linux gateways. The audit that got Vector Division here also turned up something new: some of these are not fixed controllers at all. Some of them move.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-linux-at-the-edge-01-o1', 'mission-vec-linux-at-the-edge-01', 1, 'Tell embedded Linux from bare-metal', 'Sort each description into a bare-metal microcontroller system or an embedded Linux system.'),
  ('mission-vec-linux-at-the-edge-01-o2', 'mission-vec-linux-at-the-edge-01', 2, 'Judge why the category matters', 'Choose the accurate reason the distinction between the two changes what diagnosis is even possible.'),

  ('mission-vec-linux-at-the-edge-02-o1', 'mission-vec-linux-at-the-edge-02', 1, 'Order the boot relay', 'Order the stages of a Linux gateway''s boot from power-on to userspace.'),
  ('mission-vec-linux-at-the-edge-02-o2', 'mission-vec-linux-at-the-edge-02', 2, 'Reframe the failure', 'Choose the accurate description of what "will not boot" actually means for a multi-stage boot process.'),

  ('mission-vec-linux-at-the-edge-03-o1', 'mission-vec-linux-at-the-edge-03', 1, 'Define the kernel''s job', 'Choose the accurate description of where the kernel''s responsibility ends and userspace begins.'),
  ('mission-vec-linux-at-the-edge-03-o2', 'mission-vec-linux-at-the-edge-03', 2, 'Read the console cutoff', 'Find the evidence showing exactly where the gateway''s boot output stops.'),

  ('mission-vec-linux-at-the-edge-04-o1', 'mission-vec-linux-at-the-edge-04', 1, 'Tell processes from threads', 'Choose the accurate distinction between a process and a thread.'),
  ('mission-vec-linux-at-the-edge-04-o2', 'mission-vec-linux-at-the-edge-04', 2, 'Judge the process count', 'Find the evidence showing how many userspace processes are actually running on the gateway right now.'),

  ('mission-vec-linux-at-the-edge-05-o1', 'mission-vec-linux-at-the-edge-05', 1, 'Define device files', 'Choose the accurate description of what a device file actually represents.'),
  ('mission-vec-linux-at-the-edge-05-o2', 'mission-vec-linux-at-the-edge-05', 2, 'Judge the filesystem dependency', 'State what happens to hardware access when the filesystem holding its device files is missing.'),

  ('mission-vec-linux-at-the-edge-06-o1', 'mission-vec-linux-at-the-edge-06', 1, 'Sort GPIO access methods', 'Sort each example into direct register access or Linux device-file access.'),

  ('mission-vec-linux-at-the-edge-07-o1', 'mission-vec-linux-at-the-edge-07', 1, 'Explain why serial still works', 'Choose the accurate reason a serial console reaches the gateway when the network cannot.'),
  ('mission-vec-linux-at-the-edge-07-o2', 'mission-vec-linux-at-the-edge-07', 2, 'Confirm the board is alive', 'Find the evidence proving the gateway''s processor is genuinely executing code, not simply dead.'),

  ('mission-vec-linux-at-the-edge-08-o1', 'mission-vec-linux-at-the-edge-08', 1, 'Define systemd''s role', 'Choose the accurate description of what systemd is responsible for on boot.'),
  ('mission-vec-linux-at-the-edge-08-o2', 'mission-vec-linux-at-the-edge-08', 2, 'Diagnose the missing lines', 'Find the evidence showing systemd itself was never reached, not merely that one of its services failed.'),

  ('mission-vec-linux-at-the-edge-09-o1', 'mission-vec-linux-at-the-edge-09', 1, 'Define cross compilation', 'Choose the accurate description of what cross compilation actually means.'),
  ('mission-vec-linux-at-the-edge-09-o2', 'mission-vec-linux-at-the-edge-09', 2, 'Find the target mismatch', 'Find the evidence proving this kernel image was built for the wrong target architecture.'),

  ('mission-vec-linux-at-the-edge-10-o1', 'mission-vec-linux-at-the-edge-10', 1, 'Define the root filesystem''s role', 'Choose the accurate description of what a root filesystem provides that a kernel alone cannot.'),
  ('mission-vec-linux-at-the-edge-10-o2', 'mission-vec-linux-at-the-edge-10', 2, 'Find the unverified pairing', 'Find the evidence proving the root filesystem was never verified against this specific kernel.'),

  ('mission-vec-linux-at-the-edge-11-o1', 'mission-vec-linux-at-the-edge-11', 1, 'Judge the missing logs', 'Choose the accurate reason no logging service ever produced output for this boot.'),

  ('mission-vec-linux-at-the-edge-12-o1', 'mission-vec-linux-at-the-edge-12', 1, 'Trace kernel to userspace', 'Judge whether the kernel itself failed, or succeeded with nothing valid to hand off to.'),
  ('mission-vec-linux-at-the-edge-12-o2', 'mission-vec-linux-at-the-edge-12', 2, 'Confirm the architecture mismatch', 'Find the evidence proving the deployed kernel targeted the wrong processor architecture.'),
  ('mission-vec-linux-at-the-edge-12-o3', 'mission-vec-linux-at-the-edge-12', 3, 'Confirm the filesystem mismatch', 'Find the evidence proving the root filesystem was never confirmed to match this kernel.'),
  ('mission-vec-linux-at-the-edge-12-o4', 'mission-vec-linux-at-the-edge-12', 4, 'State the diagnosis and the fix', 'Having judged all three, state why the gateway will not boot and what actually fixes it.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-linux-at-the-edge-01-o1-c1', 'mission-vec-linux-at-the-edge-01-o1', 1, 'drag_and_drop', 'Sort each description into bare-metal microcontroller or embedded Linux.', '{"items":[{"id":"i1","text":"One program, written once, running directly on the hardware with no operating system underneath it"},{"id":"i2","text":"A kernel managing many independent programs at once, each with its own protected memory"},{"id":"i3","text":"Hardware reached by writing directly to a fixed memory address that is wired to a register"},{"id":"i4","text":"Hardware reached through a filesystem, by opening a device file exposed by the kernel"}],"targets":[{"id":"mcu","label":"Bare-metal microcontroller"},{"id":"linux","label":"Embedded Linux"}]}'::jsonb, '{"correctMapping":{"i1":"mcu","i2":"linux","i3":"mcu","i4":"linux"}}'::jsonb),
  ('mission-vec-linux-at-the-edge-01-o2-c1', 'mission-vec-linux-at-the-edge-01-o2', 1, 'multiple_choice', 'Why does it matter that this gateway runs embedded Linux instead of bare-metal firmware, before any diagnosis begins?', '{"question":"Why does it matter that this gateway runs embedded Linux instead of bare-metal firmware, before any diagnosis begins?","options":[{"id":"a","text":"It does not matter, every embedded system fails the same way"},{"id":"b","text":"An operating system with a kernel, a filesystem and many independent programs can fail in places -- a mismatched build, a missing filesystem, an unstarted service -- that simply do not exist on a single-program microcontroller"},{"id":"c","text":"Linux systems are always less reliable than bare-metal firmware"},{"id":"d","text":"The distinction is only relevant for network security, not boot failures"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-linux-at-the-edge-02-o1-c1', 'mission-vec-linux-at-the-edge-02-o1', 1, 'interactive_diagram', 'Order the stages of a Linux gateway''s boot from power-on to userspace.', '{"diagramId":"linux-boot-relay","hotspots":[{"id":"bootloader1","label":"First-stage bootloader","explanation":"Minimal code run directly from fixed storage at power-on, whose only job is loading the next stage."},{"id":"bootloader2","label":"Second-stage bootloader","explanation":"Loads the kernel image into memory and starts it."},{"id":"kernel","label":"Kernel start","explanation":"Initializes hardware and memory management, then looks for a root filesystem to hand off to."},{"id":"userspace","label":"Userspace handoff","explanation":"The kernel starts the init system, which starts every other service."}],"task":"Order the stages from power-on to userspace."}'::jsonb, '{"correctOrderIds":["bootloader1","bootloader2","kernel","userspace"]}'::jsonb),
  ('mission-vec-linux-at-the-edge-02-o2-c1', 'mission-vec-linux-at-the-edge-02-o2', 1, 'multiple_choice', 'Given the boot process is a relay of several distinct stages, what does "the gateway will not boot" actually mean?', '{"question":"Given the boot process is a relay of several distinct stages, what does \"the gateway will not boot\" actually mean?","options":[{"id":"a","text":"It always means the very first bootloader stage failed"},{"id":"b","text":"It could mean any single stage failed to hand off to the next one correctly -- diagnosis means identifying exactly which handoff broke, not assuming which one"},{"id":"c","text":"It means the hardware itself is physically damaged"},{"id":"d","text":"It means the same thing as a bare-metal controller simply not powering on"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-linux-at-the-edge-03-o1-c1', 'mission-vec-linux-at-the-edge-03-o1', 1, 'multiple_choice', 'The kernel''s responsibility, versus userspace''s, is best described as...', '{"question":"The kernel''s responsibility, versus userspace''s, is best described as...","options":[{"id":"a","text":"The kernel and userspace are just two names for the same thing"},{"id":"b","text":"The kernel talks to hardware directly and manages memory and processes, then hands control to userspace, where the actual application programs and services run under the kernel''s protection"},{"id":"c","text":"Userspace runs before the kernel, to prepare hardware for it"},{"id":"d","text":"The kernel is only responsible for logging, nothing else"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-03-o2-c1', 'mission-vec-linux-at-the-edge-03-o2', 1, 'investigation', 'Where exactly does the gateway''s boot output stop?', '{"evidence":[{"id":"e1","label":"Serial console capture","detail":"Kernel messages print completely, ending at the line reporting kernel startup finished -- no lines of any kind appear after it"},{"id":"e2","label":"Network log","detail":"No packets from the gateway appear on the network in the last six hours"},{"id":"e3","label":"Power log","detail":"The gateway draws normal power from its rack supply"}],"question":"Where exactly does the gateway''s boot output stop?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-linux-at-the-edge-04-o1-c1', 'mission-vec-linux-at-the-edge-04-o1', 1, 'multiple_choice', 'The difference between a process and a thread is...', '{"question":"The difference between a process and a thread is...","options":[{"id":"a","text":"They are the same thing, just different terms"},{"id":"b","text":"A process is a running program instance with its own protected memory; a thread is a unit of execution inside a process, and threads in the same process share that process''s memory with each other"},{"id":"c","text":"A thread always has more memory than a process"},{"id":"d","text":"Only the kernel can have threads, never a normal program"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-04-o2-c1', 'mission-vec-linux-at-the-edge-04-o2', 1, 'investigation', 'How many userspace processes are actually running on the gateway right now, past the kernel?', '{"evidence":[{"id":"e1","label":"Process snapshot via serial console","detail":"Zero userspace processes reported -- only the kernel''s own internal state is visible"},{"id":"e2","label":"Hardware inventory","detail":"The gateway has a quad-core processor and 2 gigabytes of RAM"},{"id":"e3","label":"Facilities note","detail":"The gateway was installed eighteen months ago"}],"question":"How many userspace processes are actually running on the gateway right now, past the kernel?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-linux-at-the-edge-05-o1-c1', 'mission-vec-linux-at-the-edge-05-o1', 1, 'multiple_choice', 'A device file is best described as...', '{"question":"A device file is best described as...","options":[{"id":"a","text":"An ordinary text file with no connection to hardware"},{"id":"b","text":"A file, exposed by the kernel and living in the filesystem, that represents a physical or virtual device -- opening and reading or writing it interacts with the actual hardware"},{"id":"c","text":"A backup copy of a hardware driver''s source code"},{"id":"d","text":"A file that only exists while a program is actively using the device"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-05-o2-c1', 'mission-vec-linux-at-the-edge-05-o2', 1, 'multiple_choice', 'If the filesystem holding a gateway''s device files is missing or never mounted, what happens to hardware access?', '{"question":"If the filesystem holding a gateway''s device files is missing or never mounted, what happens to hardware access?","options":[{"id":"a","text":"Nothing changes, the kernel reaches hardware directly regardless"},{"id":"b","text":"Programs lose the paths they need to reach that hardware at all, even though the physical hardware itself is completely fine -- the failure is in the filesystem, not the device"},{"id":"c","text":"The hardware automatically becomes a bare-metal-style memory address instead"},{"id":"d","text":"Device files regenerate themselves from firmware automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-linux-at-the-edge-06-o1-c1', 'mission-vec-linux-at-the-edge-06-o1', 1, 'drag_and_drop', 'Sort each GPIO example into direct register access or Linux device-file access.', '{"items":[{"id":"g1","text":"Writing a bit directly to a fixed hardware register address to toggle a pin on a microcontroller"},{"id":"g2","text":"Writing a value through a GPIO device file exposed by the Linux kernel to toggle the same kind of pin"},{"id":"g3","text":"Reading a pin''s state directly from a memory-mapped register with no operating system involved"},{"id":"g4","text":"Reading a pin''s state by opening a path under the kernel''s device filesystem"}],"targets":[{"id":"register","label":"Direct register access"},{"id":"devicefile","label":"Linux device-file access"}]}'::jsonb, '{"correctMapping":{"g1":"register","g2":"devicefile","g3":"register","g4":"devicefile"}}'::jsonb),

  ('mission-vec-linux-at-the-edge-07-o1-c1', 'mission-vec-linux-at-the-edge-07-o1', 1, 'multiple_choice', 'Why does a serial console still reach the gateway when the network cannot?', '{"question":"Why does a serial console still reach the gateway when the network cannot?","options":[{"id":"a","text":"Serial is simply a faster connection than the network"},{"id":"b","text":"Serial is a simple, low-level physical link that does not depend on the operating system''s network stack or any userspace service being up -- it can carry output even from the earliest boot stages"},{"id":"c","text":"Serial consoles work only after systemd has fully started"},{"id":"d","text":"There is no real difference, either channel works identically at any boot stage"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-07-o2-c1', 'mission-vec-linux-at-the-edge-07-o2', 1, 'investigation', 'Which evidence proves the gateway''s processor is genuinely executing code, not simply dead hardware?', '{"evidence":[{"id":"e1","label":"Serial console capture","detail":"Raw kernel boot text streams over the serial line, in real time, as the board runs"},{"id":"e2","label":"Power log","detail":"The gateway draws normal power from its rack supply"},{"id":"e3","label":"Network log","detail":"No packets from the gateway appear on the network"}],"question":"Which evidence proves the gateway''s processor is genuinely executing code, not simply dead hardware?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-linux-at-the-edge-08-o1-c1', 'mission-vec-linux-at-the-edge-08-o1', 1, 'multiple_choice', 'Systemd''s role on boot is best described as...', '{"question":"Systemd''s role on boot is best described as...","options":[{"id":"a","text":"A hardware component that runs before the kernel"},{"id":"b","text":"The first real userspace program the kernel starts, responsible for starting every other service the system needs in the correct dependency order"},{"id":"c","text":"A logging utility with no control over other services"},{"id":"d","text":"An optional component most Linux systems run without"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-08-o2-c1', 'mission-vec-linux-at-the-edge-08-o2', 1, 'investigation', 'Which evidence shows systemd itself was never reached, rather than merely one of its services failing?', '{"evidence":[{"id":"e1","label":"Serial console capture","detail":"No systemd lines of any kind appear anywhere in the boot output -- not a startup banner, not a single service line, not a failure message"},{"id":"e2","label":"Facilities note","detail":"The gateway''s enclosure fan is running normally"},{"id":"e3","label":"Hardware inventory","detail":"The gateway has a quad-core processor and 2 gigabytes of RAM"}],"question":"Which evidence shows systemd itself was never reached, rather than merely one of its services failing?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-linux-at-the-edge-09-o1-c1', 'mission-vec-linux-at-the-edge-09-o1', 1, 'multiple_choice', 'Cross compilation means...', '{"question":"Cross compilation means...","options":[{"id":"a","text":"Compiling code twice to double-check it for errors"},{"id":"b","text":"Building a program on one machine (typically a powerful workstation) while targeting a different processor architecture -- the one the final device, like this gateway, actually uses"},{"id":"c","text":"Compiling several unrelated programs together into a single binary"},{"id":"d","text":"A compilation process that requires an internet connection"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-09-o2-c1', 'mission-vec-linux-at-the-edge-09-o2', 1, 'browser_simulation', 'Which build record confirms this kernel image was cross-compiled for the wrong target architecture?', '{"screen":"BUILD SYSTEM -- KERNEL IMAGE RECORDS -- GATEWAY-AGG-07","question":"Which build record confirms this kernel image was cross-compiled for the wrong target architecture?","records":[{"id":"r1","code":"BUILD_SUCCESS","detail":"Kernel image compiled with zero errors and zero warnings"},{"id":"r2","code":"TARGET_MISMATCH","detail":"Kernel image built with target architecture armv7, gateway processor is actually armv8 -- one instruction set over from what was configured"},{"id":"r3","code":"CHECKSUM_OK","detail":"Kernel image file integrity verified, no corruption during transfer"},{"id":"r4","code":"SIGNED_OK","detail":"Kernel image carries a valid build signature"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),

  ('mission-vec-linux-at-the-edge-10-o1-c1', 'mission-vec-linux-at-the-edge-10-o1', 1, 'multiple_choice', 'A root filesystem provides something a kernel alone cannot, specifically...', '{"question":"A root filesystem provides something a kernel alone cannot, specifically...","options":[{"id":"a","text":"Additional processor instructions the kernel is missing"},{"id":"b","text":"The complete set of files, libraries and programs -- including the init system -- that the kernel hands control to once its own startup is finished"},{"id":"c","text":"Extra RAM for the kernel to use"},{"id":"d","text":"A backup copy of the kernel itself in case the first one fails"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-10-o2-c1', 'mission-vec-linux-at-the-edge-10-o2', 1, 'investigation', 'Which evidence proves the root filesystem was never verified against this specific kernel before deployment?', '{"evidence":[{"id":"e1","label":"Deployment record","detail":"Root filesystem image was built for the gateway''s correct architecture separately, months earlier, with no record of any compatibility check against this kernel update before it shipped"},{"id":"e2","label":"Checksum log","detail":"The root filesystem image file itself is not corrupted"},{"id":"e3","label":"Facilities note","detail":"The gateway was installed eighteen months ago"}],"question":"Which evidence proves the root filesystem was never verified against this specific kernel before deployment?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-linux-at-the-edge-11-o1-c1', 'mission-vec-linux-at-the-edge-11-o1', 1, 'multiple_choice', 'Why did no logging service ever produce output for this boot?', '{"question":"Why did no logging service ever produce output for this boot?","options":[{"id":"a","text":"The logging service crashed and erased its own output"},{"id":"b","text":"Logging is itself a userspace service normally started by systemd -- since systemd was never reached, no logging service ever started, so no log of the failure exists past the kernel''s own raw messages"},{"id":"c","text":"Logs are stored only on the network, so they were simply unreachable"},{"id":"d","text":"The kernel deliberately disables logging during boot"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-linux-at-the-edge-12-o1-c1', 'mission-vec-linux-at-the-edge-12-o1', 1, 'multiple_choice', 'Given the kernel''s boot messages print completely and nothing appears after them, what actually happened?', '{"question":"Given the kernel''s boot messages print completely and nothing appears after them, what actually happened?","options":[{"id":"a","text":"The kernel crashed partway through its own startup"},{"id":"b","text":"The kernel finished its own startup successfully and had nothing valid to hand control to in userspace -- the failure is in the handoff, not in the kernel itself"},{"id":"c","text":"The serial cable is faulty and simply stopped transmitting"},{"id":"d","text":"The gateway lost power immediately after the kernel started"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-linux-at-the-edge-12-o2-c1', 'mission-vec-linux-at-the-edge-12-o2', 1, 'investigation', 'Which evidence proves the deployed kernel targeted the wrong processor architecture?', '{"evidence":[{"id":"e1","label":"Build record","detail":"Kernel image built with target architecture armv7, gateway processor is actually armv8 -- one instruction set over from what was configured, despite compiling with zero errors"},{"id":"e2","label":"Power log","detail":"The gateway draws normal power from its rack supply"},{"id":"e3","label":"Checksum log","detail":"The kernel image file itself is not corrupted"}],"question":"Which evidence proves the deployed kernel targeted the wrong processor architecture?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-linux-at-the-edge-12-o3-c1', 'mission-vec-linux-at-the-edge-12-o3', 1, 'investigation', 'Which evidence proves the root filesystem was never confirmed to match this kernel?', '{"evidence":[{"id":"e1","label":"Deployment record","detail":"Root filesystem image was built for the gateway''s correct architecture separately, months earlier, with no record of any compatibility check against this kernel update before it shipped"},{"id":"e2","label":"Hardware inventory","detail":"The gateway has a quad-core processor and 2 gigabytes of RAM"},{"id":"e3","label":"Facilities note","detail":"The gateway''s enclosure fan is running normally"}],"question":"Which evidence proves the root filesystem was never confirmed to match this kernel?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-linux-at-the-edge-12-o4-c1', 'mission-vec-linux-at-the-edge-12-o4', 1, 'boss_encounter', 'Having traced the kernel-to-userspace handoff, confirmed the architecture mismatch, and confirmed the filesystem mismatch, state why the gateway will not boot and what actually fixes it.', '{"stages":[{"objectiveRef":"mission-vec-linux-at-the-edge-12-o1","label":"Trace kernel to userspace"},{"objectiveRef":"mission-vec-linux-at-the-edge-12-o2","label":"Confirm the architecture mismatch"},{"objectiveRef":"mission-vec-linux-at-the-edge-12-o3","label":"Confirm the filesystem mismatch"}],"task":"State the diagnosis and the fix in one or two sentences: the kernel started but had no valid userspace to hand off to, because it was cross-compiled against the wrong target architecture and paired with a root filesystem that was never verified to match it -- the fix is to rebuild the kernel for the correct target and verify the kernel/root filesystem pairing before any future deployment."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-linux-at-the-edge-12-o1","mission-vec-linux-at-the-edge-12-o2","mission-vec-linux-at-the-edge-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-linux-at-the-edge-01-o1-c1', 'orientation', 'Ask whether the description involves one program with no operating system, or many programs managed by a kernel.', 10, 1),
  ('mission-vec-linux-at-the-edge-01-o1-c1', 'solution', 'Bare-metal: one program with no OS, direct register writes. Embedded Linux: a kernel managing many programs, hardware reached through the filesystem.', 20, 2),
  ('mission-vec-linux-at-the-edge-01-o2-c1', 'orientation', 'Think about how many more moving parts exist in a full operating system than in one program.', 10, 1),
  ('mission-vec-linux-at-the-edge-01-o2-c1', 'solution', 'A kernel, a filesystem and many independent programs open up entirely new failure categories -- mismatched builds, missing filesystems, unstarted services -- that a single-program microcontroller never has.', 20, 2),

  ('mission-vec-linux-at-the-edge-02-o1-c1', 'orientation', 'Nothing later in the relay can start before the stage before it hands off successfully.', 10, 1),
  ('mission-vec-linux-at-the-edge-02-o1-c1', 'solution', 'First-stage bootloader, then second-stage bootloader, then kernel start, then userspace handoff -- each stage only starts the next.', 20, 2),
  ('mission-vec-linux-at-the-edge-02-o2-c1', 'orientation', 'A relay with several runners can drop the baton at more than one point.', 10, 1),
  ('mission-vec-linux-at-the-edge-02-o2-c1', 'solution', '"Will not boot" could mean any single handoff broke -- the task is finding exactly which one, not assuming the first.', 20, 2),

  ('mission-vec-linux-at-the-edge-03-o1-c1', 'orientation', 'The kernel talks to hardware. Ask who talks to the kernel.', 10, 1),
  ('mission-vec-linux-at-the-edge-03-o1-c1', 'solution', 'The kernel manages hardware and memory directly, then hands control to userspace, where the actual programs run under its protection.', 20, 2),
  ('mission-vec-linux-at-the-edge-03-o2-c1', 'orientation', 'Look for the console capture, not the network or power logs.', 10, 1),
  ('mission-vec-linux-at-the-edge-03-o2-c1', 'solution', 'e1: kernel messages print completely and stop right at kernel startup finishing -- nothing after it appears at all.', 20, 2),

  ('mission-vec-linux-at-the-edge-04-o1-c1', 'orientation', 'One of the two has its own protected memory. The other shares memory with its siblings.', 10, 1),
  ('mission-vec-linux-at-the-edge-04-o1-c1', 'solution', 'A process has its own protected memory; a thread is a unit of execution inside a process, sharing that process''s memory with other threads in it.', 20, 2),
  ('mission-vec-linux-at-the-edge-04-o2-c1', 'orientation', 'Look for a process snapshot, not the hardware inventory.', 10, 1),
  ('mission-vec-linux-at-the-edge-04-o2-c1', 'solution', 'e1: zero userspace processes reported at all -- only the kernel''s own internal state is visible.', 20, 2),

  ('mission-vec-linux-at-the-edge-05-o1-c1', 'orientation', 'Think about what makes a file a "device" file specifically, versus an ordinary one.', 10, 1),
  ('mission-vec-linux-at-the-edge-05-o1-c1', 'solution', 'A device file is exposed by the kernel and represents a physical or virtual device -- opening or writing it interacts with real hardware.', 20, 2),
  ('mission-vec-linux-at-the-edge-05-o2-c1', 'orientation', 'The hardware itself is not what breaks in this scenario -- the path to it is.', 10, 1),
  ('mission-vec-linux-at-the-edge-05-o2-c1', 'solution', 'Programs lose the path to the hardware entirely, even though the hardware itself is fine -- the failure sits in the filesystem, not the device.', 20, 2),

  ('mission-vec-linux-at-the-edge-06-o1-c1', 'orientation', 'Ask whether the example writes to a fixed hardware address, or goes through a path in a filesystem.', 10, 1),
  ('mission-vec-linux-at-the-edge-06-o1-c1', 'solution', 'Direct register access: g1 and g3, writing straight to memory addresses. Device-file access: g2 and g4, going through the kernel''s filesystem.', 20, 2),

  ('mission-vec-linux-at-the-edge-07-o1-c1', 'orientation', 'Ask what the network stack depends on that a raw serial line does not.', 10, 1),
  ('mission-vec-linux-at-the-edge-07-o1-c1', 'solution', 'Serial is a simple physical link independent of the network stack or any userspace service, so it works from the earliest boot stages onward.', 20, 2),
  ('mission-vec-linux-at-the-edge-07-o2-c1', 'orientation', 'Power alone does not prove code is actually running.', 10, 1),
  ('mission-vec-linux-at-the-edge-07-o2-c1', 'solution', 'e1: raw kernel boot text streaming live over the serial line proves the processor is actually executing code.', 20, 2),

  ('mission-vec-linux-at-the-edge-08-o1-c1', 'orientation', 'Systemd is a program the kernel starts, not a hardware component.', 10, 1),
  ('mission-vec-linux-at-the-edge-08-o1-c1', 'solution', 'Systemd is the first real userspace program, responsible for starting every other service in the correct dependency order.', 20, 2),
  ('mission-vec-linux-at-the-edge-08-o2-c1', 'orientation', 'A failed service still logs something. Total silence means something earlier never happened.', 10, 1),
  ('mission-vec-linux-at-the-edge-08-o2-c1', 'solution', 'e1: not one systemd line of any kind appears, not even a failure message -- systemd itself was never reached.', 20, 2),

  ('mission-vec-linux-at-the-edge-09-o1-c1', 'orientation', 'Think about the difference between the machine doing the building and the machine that will actually run the result.', 10, 1),
  ('mission-vec-linux-at-the-edge-09-o1-c1', 'solution', 'Cross compilation builds a program on one machine while targeting a different processor architecture -- the one the final device actually uses.', 20, 2),
  ('mission-vec-linux-at-the-edge-09-o2-c1', 'orientation', 'A clean compile does not guarantee the target setting was correct.', 10, 1),
  ('mission-vec-linux-at-the-edge-09-o2-c1', 'solution', 'r2, TARGET_MISMATCH, shows the kernel was built for armv7 while the gateway is actually armv8 -- the real target mismatch.', 20, 2),

  ('mission-vec-linux-at-the-edge-10-o1-c1', 'orientation', 'The kernel manages hardware and memory. Ask what actually runs the gateway''s job day to day.', 10, 1),
  ('mission-vec-linux-at-the-edge-10-o1-c1', 'solution', 'A root filesystem supplies the complete set of files, libraries and programs -- including the init system -- the kernel hands off to once its own startup ends.', 20, 2),
  ('mission-vec-linux-at-the-edge-10-o2-c1', 'orientation', 'Look for a record about whether a compatibility check happened, not about file integrity.', 10, 1),
  ('mission-vec-linux-at-the-edge-10-o2-c1', 'solution', 'e1: the root filesystem was built separately, months earlier, with no record of ever being checked against this kernel update before deployment.', 20, 2),

  ('mission-vec-linux-at-the-edge-11-o1-c1', 'orientation', 'Logging is a service, and services are started by something specific during boot.', 10, 1),
  ('mission-vec-linux-at-the-edge-11-o1-c1', 'solution', 'Logging is a userspace service normally started by systemd -- since systemd was never reached, no logging service ever started, so nothing past the raw kernel messages exists.', 20, 2),

  ('mission-vec-linux-at-the-edge-12-o1-c1', 'orientation', 'The kernel''s messages are complete, not cut off partway through.', 10, 1),
  ('mission-vec-linux-at-the-edge-12-o1-c1', 'solution', 'The kernel finished startup successfully -- the failure is entirely in the handoff to userspace, not in the kernel itself.', 20, 2),
  ('mission-vec-linux-at-the-edge-12-o2-c1', 'orientation', 'You have seen this exact build record before, earlier this Act.', 10, 1),
  ('mission-vec-linux-at-the-edge-12-o2-c1', 'solution', 'e1: the kernel was built targeting armv7 while the gateway''s processor is armv8 -- a genuine architecture mismatch.', 20, 2),
  ('mission-vec-linux-at-the-edge-12-o3-c1', 'orientation', 'Look for the deployment record describing whether a compatibility check ever happened.', 10, 1),
  ('mission-vec-linux-at-the-edge-12-o3-c1', 'solution', 'e1: the root filesystem was built separately, months earlier, with no record of ever being checked against this kernel before deployment.', 20, 2),
  ('mission-vec-linux-at-the-edge-12-o4-c1', 'orientation', 'Combine the handoff failure, the wrong target, and the unverified filesystem pairing into one diagnosis and one fix.', 15, 1),
  ('mission-vec-linux-at-the-edge-12-o4-c1', 'solution', 'The kernel started but had no valid userspace to hand off to, because it targeted the wrong architecture and was paired with a root filesystem never verified to match it -- rebuild for the correct target, and verify the kernel/rootfs pairing before every future deployment.', 25, 2);
